pub fn properties(code: u21) u8 {
    var low: usize = 0;
    var high: usize = ranges.len;
    while (low < high) {
        const mid = low + (high - low) / 2;
        const range = ranges[mid];
        if (code < range.first) { high = mid; } else if (code > range.last) { low = mid + 1; } else return range.bits;
    }
    return 0;
}
